import React from 'react';

function About() {
  return (
    <div className="container">
      <h1 className="main-title">About Us</h1>
      <p className="about-text">
        This Link Shrinker app was created for CPIT-405 Lab 8.
        It uses React state management and routing to provide a clean and simple user experience.
      </p>
    </div>
  );
}

export default About;
